import datetime
import time
import importlib
import logging
import os
import re

from ..lteuepool import CfgFileBasedUePool
from ..exceptions import ProxyManagerConnectionException, ProxyServiceUnavailableException, \
    ProxyServiceReleaseException, ProxyManagerPluginNotFoundException
from taf.ue.proxy.mngr_client.interface import ProxyMngrClient
from taf.ue.rpc.jsonrpc.rpc import Rpc
from ..robot_api.robot_utils import get_robot_variable
from .logs import Utils


class ProxiedCfgFileBasedUePool(CfgFileBasedUePool):
    """
    Represent proxy mngr overlay on ue pool based config file class.
    Supported functionalities:
        - prepare ueproxy service using proxy manager service - prepare_ueproxy_service()
        - get ueproxy rpc client - get_ueproxy_connection_client_by()
        - release ueproxy service from finished test and enable ue monitoring feature - ueproxy_teardown()
    Example of usage:
        1. Prepare ueproxy service via ueproxy manager service. Perform this operation within TafUeXPool class
        (X - desired plugin). Ueproxy preparation should be performed inside create_device() method before exact
        ue device creation using prepare_ueproxy_service() which returns port on which ueproxy service has been started.
        Example:
            self._prepare_ueproxy_service(ue_config)
        2. Get ueproxy rpc_client by specified ip then pass it to ue device constructor parameters.
        Example:
            constructor_params = {'name': ue_name,
                                  'serial_number': serial_number,
                                  'configuration': config,
                                  'rpc_client': self.get_ueproxy_connection_client_by(ue_pc_address)
                                  }
            created_ue = instance_loader.create_class_instance(class_object=ue_class,
                                                               constructor_params=constructor_params)
        3. Cleanup after finished test. Perform this operation within TafUeXPool class (X - desired plugin) shutdown()
        using ueproxy_teardown(). This method will remove test from ueproxy service test que and enable ue monitoring
         feature if there will be no more test in progress.
        Example:
            self.ueproxy_teardown()
        Properly prepared plugin is taf.ue.android. If you want check implementation example, you can find it here:
        - https://wrgitlab.int.net.nokia.com/TAF/taf.ue.android/-/blob/master/taf/ue/android/androiduepool.py
    """

    unique_proxy_servers = set()

    def __init__(self, config_file_path=None, inline_config=None):
        super().__init__(config_file_path, inline_config)
        self.logger = logging.getLogger('ute_ue.proxy_mngr')
        self.pool_info = {}
        self.__plugin_name = self.__get_access_plugin_name(inline_config)
        self.__mngr_connections = {}
        self.__ueproxy_connections = {}
        self.__create_proxy_mngr_clients(inline_config)
        self.__download_proxy_logs = True
        self.__compress_proxy_logs = False
        self.__compress_all_logs = True

    def prepare_ueproxy_service(self, config):
        """
        Prepare ueproxy service via proxy manager service
        :param config: ue config
        """
        ue_pc_ip = config['CONSTRUCTOR_PARAMETERS']['configuration']['ue_pc_address'].lower()
        ue_pc_port = config['CONSTRUCTOR_PARAMETERS']['configuration'].get('ue_pc_port', None)
        proxy_mngr_port = config['CONSTRUCTOR_PARAMETERS']['configuration'].get('proxy_mngr_port', None)
        ueproxy_force_release = config['CONSTRUCTOR_PARAMETERS']['configuration'].get('ueproxy_force_release', False)
        self.logger.debug(f"Preparing ueproxy service on {ue_pc_ip}")
        self.logger.debug(f"Proxy mngr port: {proxy_mngr_port}")
        self.logger.debug(f"Flag ueproxy_force_release is set to: {ueproxy_force_release}")
        if not self._is_connection_to_ueproxy(ue_pc_ip):
            self.__create_connection_to_ueproxy(ue_pc_ip, ue_pc_port, proxy_mngr_port, ueproxy_force_release)
        else:
            self.logger.debug(f"Connection to {ue_pc_ip} already exist")
        self._kill_processes(ue_pc_ip, config)

        # reads config whether to download or compress the proxy logs after test suite ends
        self._check_if_download_proxy_logs(config)
        self._check_if_compress_proxy_logs(config)
        self._check_if_compress_all_logs(config)

    def release_ueproxy_service(self, ueproxy_conn):
        """
        Release ueproxy service via proxy manager service
        :param ueproxy_conn: RPC object represents ueproxy connection
        :return: None
        """
        self.logger.debug(f"Releasing ueproxy service on {ueproxy_conn.remote_url}")
        if self._is_connection_to_ueproxy(ueproxy_conn.hostname) and \
                self._is_connection_to_proxy_mngr(ueproxy_conn.hostname):
            proxy_mngr_client = self.__get_proxy_mngr_connection_by(ueproxy_conn.hostname)
            try:
                proxy_mngr_client.release_ueproxy_service(ueproxy_conn.port)
            except Exception as e:
                self.logger.exception(e, exc_info=True)
                raise ProxyServiceReleaseException(f"While releasing ueproxy service {ueproxy_conn.remote_url} occurs an error: {e}")

    def ueproxy_teardown(self, ueproxy_conn):
        """
        Teardown ueproxy service via ueproxy manager service

        :param ueproxy_conn: RPC object represents ueproxy connection
        :return: dict with ueproxy log path
        """
        self.pool_info = {"ueproxy_log_path": set(), "compress_all_logs": self.__compress_all_logs}
        self.logger.debug("Ueproxy teardown called")
        if self.__download_proxy_logs and ueproxy_conn.remote_url not in self.unique_proxy_servers:
            log_path = self._download_test_logs(ueproxy_conn)
            self.pool_info["ueproxy_log_path"].add(log_path) if log_path else None
            self.enable_ue_monitoring(ueproxy_conn)
            self.unique_proxy_servers.add(ueproxy_conn.remote_url)
        self.release_ueproxy_service(ueproxy_conn)
        self.logger.debug("Ueproxy teardown finished")
        return self.pool_info

    def get_ueproxy_connection_client_by(self, ip):
        """
        Get ueproxy connection represented by Rpc object.
        ueproxy_connections = {ip: rpc_client, ...}
        :param ip: ueproxy address
        :return: ueproxy connection represent by RPC object
        """
        self.logger.debug(f"Getting ueproxy connection for client: {ip}")
        try:
            return self.__ueproxy_connections[ip.lower()]
        except KeyError:
            raise ProxyServiceUnavailableException(f"No ueproxy service connection available under {ip}")

    def enable_ue_monitoring(self, ueproxy_conn):
        """
        Switch on/off ue monitoring feature
        :param ueproxy_conn: RPC object represents ueproxy connection
        """
        try:
            self.logger.debug(f"Enabling ue monitoring feature on: {ueproxy_conn.remote_url}")
            if self._is_connection_to_proxy_mngr(ueproxy_conn.hostname):
                proxy_mngr_client = self.__get_proxy_mngr_connection_by(ueproxy_conn.hostname)
                running_services = proxy_mngr_client.get_ueproxy_running_services()
                if ueproxy_conn and ueproxy_conn.port in running_services and \
                        running_services[ueproxy_conn.port][-1] == 'inactive':
                    ueproxy_conn.configure(configuration={"enable_ue_monitoring": "True"})
            else:
                # Proxy manager not used - backward compatibility
                self.logger.debug("Proxy mngr not used")
                ueproxy_conn.configure(configuration={"enable_ue_monitoring": "True"})
        except Exception:
            self.logger.warning("Ue monitoring configuration failed!")

    def _is_connection_to_ueproxy(self, ip):
        """
        Check if ueproxy connection exist on ip address
        :param str ip: ueproxy address
        :return bool: True / False
        """
        return ip.lower() in self.__ueproxy_connections

    def _is_connection_to_proxy_mngr(self, ip):
        """
        Check if proxy mngr connection exist on ip address
        :param str ip: proxy mngr address
        :return bool: True / False
        """
        return ip.lower() in self.__mngr_connections

    def _get_ueproxy_service(self, ip, ueproxy_force_release):
        """
        Create ueproxy service on given ip address and port
        :param ip: ueproxy ip address
        :param bool ueproxy_force_release: force release ueproxy service before running next test suite
        :return dict: created ueproxy service details
        """
        proxy_mngr_client = self.__get_proxy_mngr_connection_by(ip)
        min_required_ueproxy_ver, min_required_access_ver = self.__get_min_requirements()
        self.logger.debug("Prepare ueproxy service according to requirements: "
                          f"min_required_ueproxy_ver: {min_required_ueproxy_ver}, "
                          f"min_required_access_ver: {min_required_access_ver}, "
                          f"ue_type: {self.__plugin_name.lower()}")
        ueproxy_details = \
            proxy_mngr_client.prepare_ueproxy_server(ue_type=self.__plugin_name.lower(),
                                                     min_required_ueproxy_ver=min_required_ueproxy_ver,
                                                     min_required_access_ver=min_required_access_ver,
                                                     force_release=ueproxy_force_release)
        return ueproxy_details

    def __get_proxy_mngr_connection_by(self, ip):
        """
        Get proxy manager connection represented by ProxyMngrClient object.
        ueproxy_connections = {ip: ProxyMngrClient, ...}
        :param str ip: proxy manager address
        :return: proxy manager connection represent by ProxyMngrClient object
        """
        # Convert ip to lowercase in case on FQDN address
        lowercase_address = ip.lower()
        self.logger.debug(f"Getting proxy manager connection for: {lowercase_address}")
        try:
            return self.__mngr_connections[lowercase_address]
        except KeyError:
            raise ProxyManagerConnectionException(f"No proxy manager connection available under {lowercase_address}")

    def __is_ueproxy_alive(self, ueproxy_conn, timeout=30, interval=0.5):
        """
        Check if ueproxy is alive

        :param ueproxy_conn: RPC object represents ueproxy connection
        :param timeout: time during which service should returned available ues
        :param interval: sending request interval
        :return: None if success, raise ProxyServiceUnavailableException otherwise
        """
        self.logger.debug(f"Wait {timeout} sec for ueproxy to be alive")
        end_time = time.monotonic() + timeout
        timeout_extended = False
        while time.monotonic() < end_time:
            try:
                # call get_available_ues to check if ueproxy is ready to use
                response = ueproxy_conn.get_available_ues()
                if response:
                    if response['ue_ids']:
                        self.logger.info("Ueproxy service is alive")
                        return True
                    else:
                        self.logger.warning("Ueproxy service is alive but no UEs are available.")
                        # Extend the timeout by 30 seconds if response is received but no UEs are available
                        if not timeout_extended:
                            end_time += 30
                            timeout_extended = True
                self.logger.info("Ueproxy service is not ready yet, waiting 5 sec...")
                time.sleep(5)
            except Exception as e:
                time.sleep(interval)
                self.logger.debug(f"check if ueproxy is alive exception: {e}")
        self.__stop_ueproxy_service(ueproxy_conn)
        return False

    def __stop_ueproxy_service(self, ueproxy_conn):
        """
        Stop ueproxy service using proxy manager endpoint /services/stop
        """
        self.logger.debug(f"Stopping ueproxy service: {ueproxy_conn.remote_url}")
        if self._is_connection_to_proxy_mngr(ueproxy_conn.hostname):
            proxy_mngr_client = self.__get_proxy_mngr_connection_by(ueproxy_conn.hostname)
            proxy_mngr_client.stop_ueproxy_service(ueproxy_conn.port)
            self.logger.debug(f"Ueproxy service {ueproxy_conn.remote_url} stopped")
        else:
            self.logger.debug(f"Unable to stop {ueproxy_conn.remote_url} service due to lack of proxy mngr connection")

    def __create_proxy_mngr_clients(self, config):  # noqa: C901
        """
        Create ueproxy manager client
        :param ip: ueproxy ip address
        :param port: ueproxy port
        :return: proxy manager client instance
        """
        self.logger.debug("Creating proxy mngr clients")
        if config is not None:
            for ue_pool in config:
                ue_pc_address = config[ue_pool]['CONSTRUCTOR_PARAMETERS']['configuration']['ue_pc_address'].lower()
                proxy_mngr_port = config[ue_pool]['CONSTRUCTOR_PARAMETERS']['configuration'].get('proxy_mngr_port')
                proxy_mngr_artifactory = config[ue_pool]['CONSTRUCTOR_PARAMETERS']['configuration'].get('proxy_mngr_artifactory', '')
                if proxy_mngr_port:
                    if ue_pc_address not in self.__mngr_connections:
                        try:
                            proxy_mngr_client = ProxyMngrClient(hostname=ue_pc_address, port=proxy_mngr_port)
                            if proxy_mngr_client.is_proxy_mngr_alive():
                                try:  # Backward compatibility - new feature with taf.ue.proxy.mngr_client >= 1.2.0
                                    proxy_mngr_client.update_proxy_mngr_artifactory(proxy_mngr_artifactory=proxy_mngr_artifactory)
                                except AttributeError as exc:
                                    self.logger.warning("Please update taf.ue.proxy.mngr_client to >= 1.2.0 to use "
                                                         f"proxy mngr custom artifactory url feature: {exc}")
                                self.__mngr_connections[ue_pc_address] = proxy_mngr_client
                        except Exception as exc:
                            self.logger.debug(
                                "Proxy manager not configured for {} - {}".format(config[ue_pool]['CAPABILITIES'],
                                                                                  exc))
                        self.logger.debug(f"Created proxy mngr connection on {ue_pc_address}:{proxy_mngr_port}")
                else:
                    self.logger.debug("Proxy manager not configured for {}  - proxy_mngr_port is not provided"
                                      .format(config[ue_pool]['CAPABILITIES']))
        else:
            self.logger.warning("Config is empty. Cannot create proxy mngr client!")

    def __create_connection_to_ueproxy(self, ip, port, proxy_mngr_port, ueproxy_force_release):
        """
        Create connection to ueproxy instance with given ip
        :param ip: ueproxy ip address
        :param port: ueproxy port
        :param bool ueproxy_force_release: force release ueproxy service before running next test suite
        :return: None
        """
        if proxy_mngr_port:
            ueproxy_conn_details = self.__get_ueproxy_service_and_verify_connection(ip, ueproxy_force_release)
            self.__ueproxy_connections.update(ueproxy_conn_details)
        # ProxyMngr is not configured - backward compatibility
        else:
            ueproxy_conn_details = {
                ip: Rpc(ip, port)
            }
            self.logger.debug(f"Ueproxy connection created at: {datetime.datetime.now()} - {ip}:{port}")
            self.__ueproxy_connections.update(ueproxy_conn_details)
            self.logger.debug(f"Disabling ue monitoring on: {ip}:{port}")
            ueproxy_conn_details[ip].configure(configuration={"enable_ue_monitoring": "False"})

    def __get_ueproxy_service_and_verify_connection(self, ip, ueproxy_force_release, retries=2):
        """
        Create ueproxy service on given ip and verify connection to it.
        :param ip: ueproxy ip address
        :param bool ueproxy_force_release: force release ueproxy service before running next test suite
        :param retries: number of retries
        :return dict: created ueproxy service details
        """
        for attempt in range(1, retries + 1):
            try:
                self.logger.debug(f"Getting ueproxy service on ip: {ip} - attempt {attempt} of {retries}")
                ueproxy_details = self._get_ueproxy_service(ip, ueproxy_force_release)
                transport_type, address, port = ueproxy_details['service']['url'].split(':')
                address = address.strip('/')
                self.logger.debug("Ueproxy started at: {} - {}:{}:{}".format(ueproxy_details['start_time'],
                                                                             transport_type, address, port))
                ueproxy_conn_details = {
                    address: Rpc(address, port)
                }
                # Check if ueproxy is alive
                self.logger.debug(f"Check if ueproxy service is alive on: {address}:{port}")
                if self.__is_ueproxy_alive(ueproxy_conn_details[address]):
                    return ueproxy_conn_details
                else:
                    self.logger.debug(f"There is no connection with ueproxy service: {address}:{port}")
            except Exception as err:
                self.logger.debug(f"Following exception raised during starting ueproxy service: ({err})")

        raise ProxyServiceUnavailableException(f"Ueproxy service is not available on {ip}")

    def __get_min_requirements(self):
        """
        Return minimal ueproxy and access layer package requirements defined inside deployed plugin pool class.
        """
        self.logger.debug("Getting minimal ueproxy requirements")
        module = importlib.import_module(self.__module__)
        return module.MIN_REQUIRED_UEPROXY_VER, module.MIN_REQUIRED_ACCESS_VER

    def __get_access_plugin_name(self, config):
        """
        Return access plugin name which has been deployed.
        Class name contains plugin info as: Android, AtUe, Quectel etc.
        """

        self.logger.debug("Getting plugin name")
        if config:
            try:
                ue_id = next(iter(config), None)
                plugin_name = config.get(ue_id).get("CLASS")
                plugin_name = plugin_name[:-2] if plugin_name.endswith("Ue") else plugin_name
                self.logger.debug(f"Plugin name detected: {plugin_name}")
                return plugin_name
            except Exception as err:
                raise ProxyManagerPluginNotFoundException("While finding plugin name from CLASS"
                                                          f" parameter exception occurred: {err}")
        raise ProxyManagerPluginNotFoundException(f"Cannot find access plugin name. Config is not provided: {config}")

    def _download_test_logs(self, rpc_client, max_retries=3, timeout=2.5):  # noqa: C901
        """
        Download test execution logs from UE PC

        :param rpc_client: RpcClient object
        :param max_retries: Number of processes which will try to download the logs.
        :param timeout: Initial timeout for download logs endpoint call
        """
        self.logger.debug("Downloading test logs")
        retry_count = 0
        request_timeout = 0
        try:
            ue_pc_address = rpc_client.hostname
            # to differentiate the logs from proxies on different ue_pc
            if re.search('[a-zA-Z]', ue_pc_address):
                name_add_on = ue_pc_address.split('.')[0]
            else:
                name_add_on = ue_pc_address.replace('.', '_')
            zip_name = f"ue_proxy_logs-{name_add_on}.zip"
            self.logger.info(f"Trying to download {zip_name} file")
            while retry_count < max_retries:
                # to achieve timeouts: 2.5, 4, 6 minutes
                request_timeout = int(request_timeout) + int(timeout) if retry_count >= 1 else timeout
                request_timeout_sec = request_timeout * 60       # minutes -> seconds
                try:
                    if self._is_connection_to_proxy_mngr(rpc_client.hostname):
                        proxy_mngr_client = self.__get_proxy_mngr_connection_by(rpc_client.hostname)
                        try:
                            logs = proxy_mngr_client.download_proxy_mngr_logs_zip(ue_type=self.__plugin_name,
                                                                                  port=rpc_client.port,
                                                                                  request_timeout=request_timeout_sec)
                        except TypeError:  # Backward compatibility option
                            logs = proxy_mngr_client.download_proxy_mngr_logs_zip(ue_type=self.__plugin_name,
                                                                                  port=rpc_client.port)
                        except Exception as exc:
                            """Backward compatibility - try do download ueproxy logs in case where setup
                             does not support downloading proxy mngr logs"""
                            self.logger.debug(f"Download proxy mngr logs failed. Try to download ueproxy logs. {exc}")
                            logs = rpc_client.download_ue_proxy_logs_zip(zip_name=zip_name,
                                                                         request_type="get",
                                                                         request_timeout=request_timeout_sec)
                    else:
                        logs = rpc_client.download_ue_proxy_logs_zip(zip_name=zip_name,
                                                                     request_type="get",
                                                                     request_timeout=request_timeout_sec)
                    Utils().save_zipped_files(zip_name, get_robot_variable("OUTPUT_DIR"), logs)
                    if not self.__compress_proxy_logs:
                        Utils().unpack_zip_file(str(get_robot_variable("OUTPUT_DIR")) + f"{os.sep}{zip_name}")
                        Utils().remove_zip(str(get_robot_variable("OUTPUT_DIR")) + f"{os.sep}{zip_name}")
                        return str(get_robot_variable("OUTPUT_DIR")) + f"{os.sep}{zip_name.split('.zip')[0]}"
                    # Exit the loop if the file downloaded properly
                    return str(get_robot_variable("OUTPUT_DIR")) + f"{os.sep}{zip_name}"
                except Exception as exc:
                    self.logger.warning(f"{retry_count + 1} - Download try failed with {exc}")
                    retry_count += 1
            raise Exception(f"Unable to download ueproxy logs in {max_retries} attempts!")
        except Exception as exc:
            self.logger.warning(f"Automatic download ueproxy logs failed - {exc}. Download them manually!")

    def _kill_processes(self, ue_pc_ip, config):
        processes_to_kill = config['CONSTRUCTOR_PARAMETERS']['configuration'].get('processes_to_kill', [])

        if isinstance(processes_to_kill, str):
            cleaned_string = processes_to_kill[1:-1]
            names = cleaned_string.split(',')
            processes_to_kill = [name.strip(" '\"") for name in names]

        if processes_to_kill:
            try:
                self.logger.debug(f"Trying to kill processes from config: {processes_to_kill}")
                self.get_ueproxy_connection_client_by(ue_pc_ip).kill_processes(processes_names=processes_to_kill)
            except Exception as exc:
                self.logger.warning(f"Connection to ueproxy failed - {exc}.")

    def _check_if_download_proxy_logs(self, config):
        download_proxy_logs = config['CONSTRUCTOR_PARAMETERS']['configuration'].get('download_proxy_logs', True)

        formatted_resp = "ON" if download_proxy_logs else "OFF"
        self.logger.debug(f"Downloading proxy logs is turned {formatted_resp}")

        self.__download_proxy_logs = download_proxy_logs

    def _check_if_compress_proxy_logs(self, config):
        compress_proxy_logs = config['CONSTRUCTOR_PARAMETERS']['configuration'].get('compress_proxy_logs', False)

        formatted_resp = "ON" if compress_proxy_logs else "OFF"
        self.logger.debug(f"Compressing proxy logs to *.ZIP is turned {formatted_resp}")

        self.__compress_proxy_logs = compress_proxy_logs

    def _check_if_compress_all_logs(self, config):
        compress_all_logs = config['CONSTRUCTOR_PARAMETERS']['configuration'].get('compress_all_logs', True)
        self.logger.debug(f"Compressing all logs to one *.ZIP package is turned {'ON' if compress_all_logs else 'OFF'}")
        self.__compress_all_logs = compress_all_logs
